import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"04-3 ERC-20 入门：转账、授权与 allowance 的区别","description":"","frontmatter":{},"headers":[],"relativePath":"04-security/erc20.md","filePath":"04-security/erc20.md","lastUpdated":1791601077000}'),r={name:"04-security/erc20.md"};function o(p,a,l,i,d,c){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="_04-3-erc-20-入门-转账、授权与-allowance-的区别" tabindex="-1">04-3 ERC-20 入门：转账、授权与 allowance 的区别 <a class="header-anchor" href="#_04-3-erc-20-入门-转账、授权与-allowance-的区别" aria-label="Permalink to &quot;04-3 ERC-20 入门：转账、授权与 allowance 的区别&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：不创建代币、不碰真钱。只弄清 ETH 与 ERC-20 的区别，以及为什么钱包里的“授权成功”不等于“付款成功”。</p></blockquote><h2 id="先区分-eth-和-erc-20" tabindex="-1">先区分 ETH 和 ERC-20 <a class="header-anchor" href="#先区分-eth-和-erc-20" aria-label="Permalink to &quot;先区分 ETH 和 ERC-20&quot;">​</a></h2><p><strong>ETH</strong> 是以太坊网络的原生资产，可以用于支付网络交易费等。</p><p><strong>ERC-20</strong> 是一套常见的代币接口标准。许多代币的余额不是由以太坊原生 ETH 余额字段记录，而是由某个 Token 合约管理。</p><p>你可以把它想成：</p><ul><li>ETH：系统原生支持的资产。</li><li>ERC-20：开发者在 Token 合约里按通用接口维护的账本。</li></ul><p>因此“把 ETH 转给某地址”和“调用 Token 的 transfer 转代币”，不是同一件操作。</p><h2 id="从最常见的五个函数学起" tabindex="-1">从最常见的五个函数学起 <a class="header-anchor" href="#从最常见的五个函数学起" aria-label="Permalink to &quot;从最常见的五个函数学起&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ERC-20 接口</th><th>白话解释</th></tr></thead><tbody><tr><td><code>balanceOf(user)</code></td><td>查询 user 的代币余额</td></tr><tr><td><code>transfer(to, amount)</code></td><td>自己把代币转给 to</td></tr><tr><td><code>approve(spender, amount)</code></td><td>允许 spender 最多花费自己多少额度</td></tr><tr><td><code>allowance(owner, spender)</code></td><td>查 owner 给 spender 的剩余授权额度</td></tr><tr><td><code>transferFrom(from, to, amount)</code></td><td>被授权者按照规则从 from 转代币给 to</td></tr></tbody></table><h2 id="最容易混淆的是-approve-和-transferfrom" tabindex="-1">最容易混淆的是 approve 和 transferFrom <a class="header-anchor" href="#最容易混淆的是-approve-和-transferfrom" aria-label="Permalink to &quot;最容易混淆的是 approve 和 transferFrom&quot;">​</a></h2><p>假设你有 100 枚某代币，想让一个 DApp 合约替你支付 30 枚。</p><p><strong>第一笔交易：授权</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户调用 Token.approve(DApp地址, 30)</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>Token 合约记录：DApp 允许从用户余额使用最多 30</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>授权成功，但代币还在用户账户中</span></span></code></pre></div><p><strong>第二笔交易：实际花费</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DApp 调用 Token.transferFrom(用户, 收款方, 30)</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>Token 合约验证余额、授权与其他规则</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>符合条件才转账，并按实现更新授权</span></span></code></pre></div><p>关键区别：<strong>approve 主要修改授权额度，不是把钱立即转给对方</strong>。</p><h2 id="为什么-无限授权-危险" tabindex="-1">为什么“无限授权”危险？ <a class="header-anchor" href="#为什么-无限授权-危险" aria-label="Permalink to &quot;为什么“无限授权”危险？&quot;">​</a></h2><p>一些 DApp 让你授权一个非常大的金额，之后它就可以在授权和余额允许的范围内重复使用代币，而不必每次由你再单独 approve。</p><p>如果 DApp 本身恶意、合约被攻击或权限被控制，你暴露的风险可能远大于原计划支付的 30 枚。</p><p>所以新手操作真实钱包时必须看清：</p><ul><li>授权给<strong>哪个合约地址</strong>？</li><li>授权的是<strong>哪一种 Token</strong>？</li><li>授权额度是多少？</li><li>是否有需要时撤销授权的渠道？</li></ul><h2 id="实际标准还有很多边界" tabindex="-1">实际标准还有很多边界 <a class="header-anchor" href="#实际标准还有很多边界" aria-label="Permalink to &quot;实际标准还有很多边界&quot;">​</a></h2><p>不同代币实现可能存在手续费、非标准返回值、特殊回调或冻结规则。生产工程通常使用经过维护与审阅的库（例如 <a href="https://docs.openzeppelin.com/contracts/" target="_blank" rel="noreferrer">OpenZeppelin Contracts</a>）并检查目标 Token 的特殊行为，不要把互联网上随便复制的 token 合约当成安全基础。</p><h2 id="免费练习-只观察-不发送资金" tabindex="-1">免费练习：只观察，不发送资金 <a class="header-anchor" href="#免费练习-只观察-不发送资金" aria-label="Permalink to &quot;免费练习：只观察，不发送资金&quot;">​</a></h2><p>在 Remix 中回顾 <a href="/02-evm/abi">ABI 章节</a>：</p><ol><li>找出 <code>transfer(address,uint256)</code> 的函数签名。</li><li>用 <code>cast sig &#39;transfer(address,uint256)&#39;</code> 生成 selector。</li><li>画一个两笔交易的示意图：“用户 approve → DApp transferFrom”。</li><li>自己解释：为什么第一笔成功，并不意味着第二笔一定成功？</li></ol><details><summary>参考答案</summary><p>第一次成功仅代表授权状态更新。第二次调用时仍可能余额不足、授权额度不够、代币实现拒绝转账、调用者错误或者交易本身失败。</p></details><p><strong>本课验收</strong>：能分清 ETH、Token、balance、allowance、approve、transferFrom；懂得不能随意给不认识的 DApp 无限授权。</p><p>下一课：<a href="/05-project/">Escrow：把前面学的知识组合成一个完整项目</a>。</p>`,30)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
